  "about.pageTitle": "Luminous StockHaven — درباره ما",
  "about.founderHeading": "📖 درباره بنیان‌گذار",
  "about.founder.p1": "سلام، من کانسپسیون هستم، بنیان‌گذار Luminous StockHaven.",
  "about.founder.p2": "من از یک شرکت بزرگ فناوری نیامده‌ام و در دفتر یک شرکت بزرگ نمی‌نشینم. من یک خرده‌فروش کوچک هستم، درست مثل شما. پنج فروشگاه اینترنتی را مدیریت می‌کنم که در زمینه کتاب و لوازم دست‌ساز برای دوستداران کتاب تخصص دارند.\nمانند بسیاری از خرده‌فروشان مستقل، به نقطه شکست رسیدم وقتی تلاش می‌کردم موجودی چند مکان را مدیریت کنم، شماره‌های ISBN ناشران را در کنار SKUهای دست‌ساز خودم دنبال کنم و سفارش‌های تأمین‌کنندگان را با صفحات گسترده دست‌وپاگیر انجام دهم. وقتی دنبال برنامه‌ای برای کمک گشتم، شش گزینه مختلف را امتحان کردم. هر کدام یا کاملاً ناقص بودند، یا به‌طرز باورنکردنی گیج‌کننده، یا سودجو — برای ابزارهای پایه ماهانه صدها دلار می‌گرفتند.",
  "about.founder.p3": "از صنعتی که خالقان مستقل را استثمار می‌کند ناامید شدم و تصمیم گرفتم راه‌حل خودم را بسازم. Luminous StockHaven را از روی ضرورت ساختم تا کسب‌وکارهای خودم را تمیز، کارآمد و با آرامش کامل اداره کنم.",
  "about.founder.p4": "تصمیم گرفتم این پلتفرم را با قیمتی صادقانه و مقرون‌به‌صرفه در اختیار عموم قرار دهم، زیرا هر خرده‌فروش کوچکی سزاوار ابزارهایی است که واقعاً کار کنند، بدون اینکه درآمدش را به خطر بیندازد. ما به‌طور مستقل مالکیت داریم، از جامعه خود به‌شدت محافظت می‌کنیم و توسط یک خرده‌فروش، برای خرده‌فروشان ساخته شده‌ایم.",
  "notice.ariaLabel": "اطلاعیه علائم تجاری و حق نشر",
