  "notice.intro": "این برنامه را ساختم چون ۵ فروشگاه را اداره می‌کنم و از اینکه با نرم‌افزارهای گیج‌کننده چندصد دلاری سرم کلاه برود خسته شده بودم. این برنامه برای محافظت از هنرمندان مستقل، صنعتگران، کتاب‌فروشان و فروشگاه‌های محلی ساخته شده است.",
