  "billing.cancelError.purchaseContractMismatch": "سابقه صورت‌حساب با این کسب‌وکار مطابقت ندارد، بنابراین نمی‌توانیم آن را در اینجا لغو کنیم. هیچ‌چیز تغییر نکرد — لطفاً با پشتیبانی تماس بگیرید.",
  "billing.cancelError.stripeNotConfigured": "پرداخت‌ها قابل دسترسی نبودند. هیچ‌چیز تغییر نکرده است — لطفاً دوباره تلاش کنید یا با پشتیبانی تماس بگیرید.",
  "billing.cancelError.subscriptionPaidThroughUnverified": "نتوانستیم تاریخ پرداخت‌شده شما را تأیید کنیم. هیچ‌چیز تغییر نکرد — لطفاً دوباره تلاش کنید یا با پشتیبانی تماس بگیرید.",
  "billing.cancelError.alreadyEnded": "این اشتراک از قبل پایان یافته است، بنابراین چیز دیگری برای لغو وجود ندارد.",
  "billing.cancelError.subscriptionEventHistoryIncomplete": "سابقه صورت‌حساب شما پیش از لغو این مورد نیاز به بررسی دارد. هیچ‌چیز تغییر نکرد — لطفاً با پشتیبانی تماس بگیرید.",
  "billing.cancelError.eventRequiresReview": "سابقه صورت‌حساب شما پیش از لغو این مورد نیاز به بررسی دارد. هیچ‌چیز تغییر نکرد — لطفاً با پشتیبانی تماس بگیرید.",
  "billing.cancelError.subscriptionCancellationUnavailable": "لغو کامل نشد. هیچ‌چیز تغییر نکرد — اشتراک و دسترسی شما دقیقاً مانند قبل هستند. لطفاً دوباره تلاش کنید یا با پشتیبانی تماس بگیرید.",
  "billing.readiness.ariaLabel": "آمادگی واقعی پرداخت Essentials",
  "billing.readiness.title": "پرداخت Essentials — بررسی واقعی ایمنی حساب",
  "billing.readiness.body": "سوابق واقعی اشتراک و دوره آزمایشی را بدون خرید هیچ‌چیز بررسی کنید. حساب Business رایگان شما و نمونه پیژامه شما بدون تغییر باقی می‌مانند. این کار پرداخت Stripe را باز نمی‌کند، از کارتی مبلغی کسر نمی‌کند و طرحی را تغییر نمی‌دهد.",
  "billing.readiness.checking": "در حال بررسی سوابق حساب…",
