  "billing.readiness.ready": "پرداخت Stripe آماده است — کلیدها، تأیید وب‌هوک و گواهی‌ها همگی تأیید شده‌اند.",
  "billing.readiness.complimentaryProtected": "فضای کاری Business رایگان شما محافظت شده است. نباید به حساب آزمایشی پولی Essentials تبدیل شود.",
  "billing.readiness.environmentIncomplete": "اعتبارنامه‌های پرداخت Stripe، تأیید وب‌هوک یا نشانی بازگشت برنامه همگی تأیید نشدند. هیچ پرداختی نمی‌تواند شروع شود.",
  "billing.readiness.ownerHasHistory": "این مالک سابقه اشتراک یا دوره آزمایشی قبلی دارد. پرداخت دومی نباید ایجاد شود.",
  "billing.readiness.trialAlreadyUsed": "دوره آزمایشی مقدماتی از قبل استفاده یا رزرو شده است. هیچ دوره آزمایشی تکراری نمی‌تواند شروع شود.",
  "billing.readiness.trialEligibilityUnverified": "واجد شرایط بودن دوره آزمایشی یک‌باره برای این مالک تأیید نشده است. پرداخت مسدود باقی می‌ماند.",
  "billing.readiness.testModeUnverified": "سوابق حساب قابل خواندن هستند، اما مهار امن حالت آزمایشی Stripe و انجام تمدید پولی تأیید نشده‌اند. پرداخت مسدود باقی می‌ماند.",
