  "billing.readiness.ownershipMismatch": "مالکیت حساب یا سوابق صورت‌حساب پیش از شروع هر اشتراکی نیاز به بررسی دارند.",
  "billing.readiness.catalogUnverified": "تعریف پرداخت سرور تأییدشده 14.99 دلار در ماه نیاز به تأیید دارد.",
  "billing.readiness.auditUnavailable": "بررسی فقط‌خواندنی سرور در دسترس نبود. هیچ پرداخت یا تغییر حسابی رخ نداد.",
  "billing.dryRun.ariaLabel": "شبیه‌سازی آزمایشی ارتقا",
  "billing.dryRun.title": "Essentials → Business — شبیه‌سازی تمرینی",
  "billing.dryRun.body": "قوانین ارتقای پیشنهادی را با سوابق کاملاً ساختگی در این مرورگر تمرین کنید. این کار نمونه واقعی TEST — شلوار پیژامه، فضای کاری Business فعلی شما، Stripe، دوره‌های آزمایشی، اشتراک‌ها یا موجودی شما را نمی‌خواند یا تغییر نمی‌دهد.",
