  "billing.dryRun.example": "مثال: Essentials (14.99 دلار در ماه) → Business (29.99 دلار در ماه)، پیش از هر مالیات قابل اعمال.",
  "billing.dryRun.preserved": "همان اشتراک حفظ شد، یک دوره آزمایشی اصلی حفظ شد و موجودی ساختگی پیژامه بدون تغییر ماند. مشتری مثال روی Essentials باقی می‌ماند تا زمانی که تمدید پولی واقعی و تأییدشده توسط ارائه‌دهنده تغییر دسترسی را توجیه کند.",
