  "settings.details.taxModeHint": "حالت ثابت از نرخ شما برای هر سفارش جدید استفاده می‌کند. حالت خودکار مالیات سفارش جدید را با نرخ پایه ایالت مشتری پر می‌کند، به‌محض اینکه ایالت در سفارش باشد، و اگر ایالت تغییر کند دوباره آن را پر می‌کند. این‌ها نرخ‌های پایه ایالت‌ها هستند — مالیات‌های محلی ممکن است بیشتر اضافه کنند. سفارشی بدون ایالت، یا از خارج از آمریکا، از نرخ ثابت شما در بالا استفاده می‌کند.",
  'settings.details.gs1Prefix': "پیش‌شماره شرکت GS1",
  'settings.details.gs1PrefixHint': "فقط اگر از GS1 مجوز پیش‌شماره دارید. آن را یک بار تنظیم کنید تا سازنده کد در فرم محصول بتواند کدهای واقعی خرده‌فروشی UPC و EAN را از شماره‌های خودتان بسازد — هر کدام فقط یک بار استفاده می‌شود و هرگز دوباره استفاده نمی‌شود. اگر ندارید خالی بگذارید؛ برنامه هرگز پیش‌شماره‌ای جعل نمی‌کند.",
  'settings.details.gs1LearnMore': "با GS1 تازه آشنا شده‌اید؟ اگر در کشور خودتان زندگی می‌کنید، از پیوند آن کشور برای دانستن بیشتر استفاده کنید؛ اگر در ایالات متحده زندگی می‌کنید، از پیوند GS1 US استفاده کنید.",
