  "settings.logout": "خروج",
  "settings.pastDue.body": "آخر پرداخت شما انجام نشد. از زمان پرداخت ناموفق، به مدت ۱۴ روز استفاده کامل را حفظ می‌کنید تا آن را اصلاح کنید. اگر اصلاح نشود، اشتراک لغو می‌شود، فضای کاری به مدت ۱۵ روز فقط قابل مشاهده می‌شود و سپس حساب و تمام اطلاعات آن حذف می‌شود. پرداخت در هر زمانی پیش از حذف، همه چیز را برمی‌گرداند. اگر مطمئن نیستید چه کار کنید، با پشتیبانی در theluminousbookshop@outlook.com تماس بگیرید.",
