  "payroll.dd.steps.body": "1. به یک حساب بانکی تجاری نیاز دارید که بتواند پرداخت‌های ACH ارسال کند. 2. از هر عضو تیم یک فرم اجازه امضاشده بگیرید - یک چک باطل‌شده به تأیید شماره‌ها کمک می‌کند. 3. حقوق و دستمزد را 2-3 روز کاری پیش از روز پرداخت ارسال کنید تا پول به‌موقع برسد. 4. بیشتر ایالت‌ها رضایت کتبی عضو تیم را لازم دارند. این برنامه فرم‌ها را جمع‌آوری می‌کند و شما را در مراحل راهنمایی می‌کند - ارسال واقعی پول از طریق بانک خودتان انجام می‌شود.",
