  "auth.sameEmailNotice": "برنامه ما را از Google Play یا App Store دارید؟ اینجا از همان ایمیل استفاده کنید — همان که با آن وارد برنامه می‌شوید — تا فروشگاه و موجودی شما همراهتان بیاید. یک ایمیل متفاوت یک فروشگاه کاملاً جدید و خالی شروع می‌کند.",
