  "recovery.emailMeCodeHint": "اگر یک ایمیل پشتیبان تنظیم کرده باشید، یک کد 6 رقمی به آنجا ارسال می‌کنیم. برای محافظت از حساب شما، این صفحه همیشه به یک شکل پاسخ می‌دهد — چه کدی ارسال شده باشد چه نشده باشد.",
