  "recovery.doneBody": "ایمیل حساب شما تغییر کرد و این ورود اکنون دوباره ورود عادی شماست. خوش برگشتید.",
  "recovery.doneButton": "ادامه به فروشگاه من",
  "settings.security.title": "امنیت و کلیدهای یدکی",
  "settings.security.description": "کلیدهای یدکی خود را پیش از آنکه به آن‌ها نیاز پیدا کنید تنظیم کنید: اگر هرگز دسترسی به ایمیل حساب خود را از دست بدهید، آن‌ها راه برگشت فروشگاه شما هستند.",
  "settings.security.genericError": "مشکلی پیش آمد. لطفاً دوباره تلاش کنید.",
  "settings.security.accountEmail": "ایمیل حساب",
  "settings.security.backupCodesTitle": "کدهای پشتیبان",
  "settings.security.backupCodesDesc": "کلیدهای یدکی یک‌بارمصرف. آن‌ها را چاپ کنید یا بنویسید و در جای امنی نگه دارید — هر کدام اگر ایمیل خود را از دست بدهید می‌تواند شما را یک بار برگرداند.",
  "settings.security.codesRemaining": "کدهای پشتیبان استفاده‌نشده باقی‌مانده: {count}",
