  "support.contextNote": "تا بتوانیم مشکل را پیدا کنیم، یادداشت شما به‌طور خودکار شامل صفحه‌ای که در آن هستید، کسب‌وکار و نقش شما اگر انتخاب شده باشد، طرح شما، زبان برنامه شما، و نوع تلفن یا مرورگری که استفاده می‌کنید می‌شود. هرگز شامل محصولات، موجودی یا فروش‌های شما نمی‌شود.",
  "support.description": "چیزی خراب است، چیزی اشتباه به نظر می‌رسد، یا ایده‌ای برای اشتراک دارید؟ اینجا به ما بگویید — یادداشت شما مستقیم به تیم پشت برنامه می‌رود.",
