  "support.sentBody": "ما هر گزارش را می‌خوانیم. اگر به جزئیات بیشتری نیاز داشته باشیم، به ایمیل حساب شما می‌نویسیم.",
  "support.sentTitle": "متشکرم — گزارش شما ارسال شد.",
