  "print.style.previewText": "روباه قهوه‌ای سریع از روی سگ تنبل می‌پرد. 1234567890",
  "training.lessons.owner-shipping-labels.step1": "مرکز چاپ در هر دو طرح سبک برچسب ارسال دارد: سفارش مشتری را انتخاب کنید و برچسب 4×6 با نام و نشانی خریدار و کسب‌وکار شما به‌عنوان فرستنده چاپ کنید.",
  "training.lessons.owner-shipping-labels.step2": "برچسب سفیدبرچسب است، مانند هر سند مشتری: فقط نام کسب‌وکار شما را دارد — هرگز نام این برنامه را نه — تا بسته‌ای از فروشگاه شما چنان به نظر برسد که از فروشگاه شما آمده است.",
  "training.lessons.owner-shipping-labels.step3": "نشانی مشتری تا 90 روز پس از آخرین سفارشش همراه سفارش‌هایش نگه داشته می‌شود و برچسب وقتی نشانی ذخیره‌شده سفارش وجود داشته باشد از آن شروع می‌شود؛ نشانی‌ای که هنگام چاپ برای یک برچسب یک‌باره تایپ شود برگردانده و ذخیره نمی‌شود. نام همچنان از سفارش پر می‌شود تا برچسب با مدارک مطابقت داشته باشد.",
  "training.lessons.owner-shipping-labels.step4": "برچسب از همان چهار اتصال همه برچسب‌ها چاپ می‌شود — بلوتوث، وای‌فای، اترنت و USB — و چاپگر حرارتی 4×6 اندازه استاندارد آن است.",
  "training.lessons.owner-shipping-labels.step5": "هزینه پست را از شرکت حمل‌ونقل خریدید؟ در همین بخش می‌توانید فایل برچسب شرکت حمل‌ونقل را — PDF، PNG یا JPG — بارگذاری کنید تا برای همیشه روی سفارش بماند: سند شما، در دسترس اگر اتفاقی بیفتد. با اندازه واقعی 4×6 چاپ می‌شود. برنامه هرگز هزینه پست نمی‌فروشد، پس قیمت شرکت حمل‌ونقل تنها قیمت است — و همیشه قیمت درست.",
  "training.lessons.owner-shipping-labels.title": "برچسب‌های ارسال برای سفارش‌های مشتری",
  "training.lessons.print-shipping-label.step1": "وقتی سفارشی آماده ارسال است، مرکز چاپ را باز کنید، سبک برچسب ارسال را انتخاب کنید و سپس سفارش مشتری را برگزینید. نام خریدار از سفارش پر می‌شود.",
  "training.lessons.print-shipping-label.step2": "نشانی‌ای را که بسته به آن می‌رود بررسی کنید. وقتی سفارش نشانی مشتری را دارد — که تا 90 روز پس از آخرین سفارشش نگه داشته می‌شود — برای شما پر می‌شود؛ نشانی‌ای که هنگام چاپ تایپ می‌کنید ذخیره نمی‌شود، پس پیش از چاپ کد پستی و سطر آخر را با دقت بررسی کنید.",
  "training.lessons.print-shipping-label.step3": "نام کسب‌وکار شما در بالا به‌عنوان فرستنده چاپ می‌شود. اگر می‌خواهید نشانی‌تان هم روی برچسب باشد، آن را در کادر نشانی فرستنده بنویسید؛ اگر ترجیح می‌دهید دیده نشود، خالی بگذارید.",
  "training.lessons.print-shipping-label.step4": "روی برچسب 4×6 چاپ کنید — چاپگر حرارتی برچسب انتخاب معمول است — یا با دکمه چاپ مرورگر روی هر چاپگری. برچسب را صاف روی بسته بچسبانید، جایی که روی لبه تا نشود.",
  "training.lessons.print-shipping-label.step5": "اگر هزینه پست از شرکت حمل‌ونقل خریده شده، به جایش فایل برچسب آن‌ها را روی سفارش ذخیره کنید: PDF، PNG یا JPG ای را که شرکت حمل‌ونقل به شما داده در بخش برچسب شرکت حمل‌ونقل شما بارگذاری کنید. به عنوان سند شما روی سفارش می‌ماند و با اندازه واقعی 4×6 چاپ می‌شود — و برچسب نشانی خود برنامه همیشه آنجاست وقتی ترجیح می‌دهید از آن استفاده کنید.",
  "training.lessons.print-shipping-label.title": "یک برچسب ارسال چاپ کنید",
