  "apiErrors.locationsCreateReserved": "فقط مالک، یا عضوی از تیم که مالک به او اجازهٔ افزودن مکان‌ها را داده است، می‌تواند مکان اضافه کند.",
  "settings.policies.title": "سیاست‌ها و شرایط فروشگاه شما",
  "settings.policies.ownerDescription": "فروشگاه شما، قوانین شما. سیاست‌های فروشگاه و شرایط و ضوابط خود را اینجا بنویسید — آن‌ها را تایپ کنید یا یک فایل بارگذاری کنید. هر عضو جدید تیم یک بار هنگام شروع آن‌ها را می‌بیند و همه تیم شما می‌توانند هر وقت بخواهند اینجا بخوانندشان. فقط شما می‌توانید آن‌ها را تغییر دهید.",
  "settings.policies.memberDescription": "سیاست‌ها و شرایط خود فروشگاه شما، نوشته مالک. فقط مالک می‌تواند آن‌ها را تغییر دهد.",
