  "staffWelcome.policiesIntro": "پیش از شروع: سیاست‌ها و شرایط فروشگاه شما، نوشته مالک.",
  "plansLib.includes.storePolicies": "سیاست‌ها و شرایط خود فروشگاه شما در تنظیمات، برای خواندن همه تیمتان",
  "apiErrors.businessPoliciesOwnerOnly": "فقط مالک می‌تواند سیاست‌ها و شرایط این فروشگاه را تغییر دهد.",
  "apiErrors.policyFileInvalid": "یک فایل PDF، متنی، Word یا OpenDocument زیر ۲ مگابایت بفرستید.",
  "apiErrors.policyTextTooLong": "این سند برای تایپ کردن اینجا خیلی طولانی است. به جایش می‌توانید آن را به صورت فایل بارگذاری کنید.",
  "training.lessons.owner-store-policies.title": "سیاست‌ها و شرایط فروشگاه شما",
  "training.lessons.owner-store-policies.step1": "تنظیمات را باز کنید و کارت سیاست‌ها و شرایط فروشگاه را پیدا کنید. دو سند دارد: سیاست‌های فروشگاه شما — قوانین خانه برای فروشگاهتان — و شرایط و ضوابط شما.",
  "training.lessons.owner-store-policies.step2": "هر سند را می‌توان همان جا تایپ کرد، یا به صورت فایل بارگذاری کرد (PDF، متنی، Word یا OpenDocument، تا ۲ مگابایت). یکی یا دیگری: ذخیره متن جای فایل را می‌گیرد و بارگذاری فایل جای متن را. حذف یک سند آن را پاک می‌کند.",
  "training.lessons.owner-store-policies.step3": "تیم شما هر دو سند را یک بار می‌بیند، در صفحه خوش‌آمد هنگام نخستین شروع، و می‌تواند هر وقت بخواهد در تنظیمات خودش بخواندشان. برای تیم شما فقط خواندنی‌اند — فقط شما می‌توانید آن‌ها را بنویسید یا تغییر دهید.",
  "training.lessons.owner-store-policies.step4": "هر کسب‌وکار اسناد خودش را نگه می‌دارد: آنچه اینجا می‌نویسید فقط از آنِ این فروشگاه است و هرگز در کسب‌وکار دیگری دیده نمی‌شود. شرایط و سیاست‌های خود Luminous StockHaven در تنظیمات کنار اسناد شما زندگی می‌کنند و همه می‌توانند آن‌ها را هم بخوانند.",
  "training.lessons.welcome-basics.step5": "سیاست‌ها و شرایط فروشگاه شما یک بار در صفحه خوش‌آمدتان نشان داده می‌شوند و در تنظیمات زندگی می‌کنند، جایی که می‌توانید هر وقت بخواهید بخوانیدشان.",
  "apiErrors.policyDocNotFound": "آن سند یکی از این دو نیست.",
