  "staff.memberDialog.staffAccessHint": "فقط مدیران — با این علامت، این مدیر فهرست کامل کارکنان را می‌بیند، فقط برای خواندن. بدون آن، مدیر فقط کارت خودش را می‌بیند. این علامت برای کارکنان کاری نمی‌کند.",
