  "staffLib.perm.alertsView": "دیدن هشدارهای موجودی کم",
  "staffLib.perm.productsReorder": "تغییر نقاط سفارش مجدد",
  "staffLib.area.lowStockAccess": "موجودی کم",
  "staff.memberDialog.lowStockAccessHint": "با علامت اول، این شخص هشدارهای موجودی کم را می‌بیند — کادر «نیاز به توجه دارد»، صفحه موجودی کم و نشانه‌های سطح کم. با علامت دوم، می‌تواند نقطه سفارش مجدد یک محصول را تغییر دهد؛ بدون آن، کادر نقطه سفارش مجدد همچنان دیده می‌شود، اما تغییری در آن ذخیره نخواهد شد.",
  "apiErrors.reorderChangeReserved": "فقط مالک، یا عضوی از تیم که مالک به او اجازهٔ تغییر نقاط سفارش مجدد را داده است، می‌تواند نقطه سفارش مجدد را تغییر دهد.",
  "apiErrors.alertsViewReserved": "فقط مالک، یا عضوی از تیم که مالک به او اجازهٔ دیدن هشدارهای موجودی کم را داده است، می‌تواند هشدارهای موجودی کم را ببیند.",
  "apiErrors.quizRequired": "این درس با یک آزمون کوتاه به پایان می‌رسد — برای تمام کردن درس، درست پاسخ دهید.",
