  "settings.policyQuiz.addMc": "افزودن پرسش چندگزینه‌ای",
  "settings.policyQuiz.addOpen": "افزودن پرسش باز",
  "settings.policyQuiz.correct": "درست",
  "settings.policyQuiz.empty": "هنوز پرسشی نیست. بدون پرسش، این آموزش فقط خواندن است.",
  "settings.policyQuiz.expected": "پاسخ مورد انتظار",
  "settings.policyQuiz.expectedHint": "پاسخی که انتظار دارید، با کلمات خودتان. پاسخی که تقریباً کلمه به کلمه مطابقت داشته باشد همان‌جا درست شمرده می‌شود؛ بقیه برای نگاه شما نزدتان می‌آیند.",
  "settings.policyQuiz.hint": "درباره این سند برای تیم خود پرسش بنویسید. شخص وقتی در پرونده کارکنانش این آموزش را برای او تیک می‌زنید، در آموزش به آن‌ها پاسخ می‌دهد. هیچ محدودیتی برای تعداد پرسش‌هایی که می‌نویسید وجود ندارد.",
  "settings.policyQuiz.mcLabel": "چندگزینه‌ای",
