  "settings.policyQuiz.passLine": "خط قبولی",
  "settings.policyQuiz.passLineHint": "نمره‌ای — با شمارش فقط پاسخ‌های چندگزینه‌ای — که شخص برای تمام کردن این آموزش به آن نیاز دارد.",
  "settings.policyQuiz.question": "پرسش",
