  "apiErrors.profileOwnerNameOnly": "فقط مالک کسب‌وکار می‌تواند نام مالک را تنظیم کند.",
  "apiErrors.profilePhotosApproveOwnerOnly": "فقط مالک کسب‌وکار می‌تواند عکس‌های تیم را تأیید کند.",
  "apiErrors.profilePhotosNoneWaiting": "این عضو تیم هیچ عکسی در انتظار تأیید ندارد.",
  "apiErrors.profileOwnerNameTooLong": "نام خود را به ۸۰ نویسه یا کمتر محدود کنید.",
  "training.lessons.your-profile-photo.title": "عکس پروفایل شما",
  "training.lessons.your-profile-photo.step1": "عکس شما در بالای برنامه، در صفحه کارکنان و در کنار پیام‌هایتان، در کنار نامتان ظاهر می‌شود — پس از آنکه مالک آن را تأیید کند. تا آن زمان، فقط حروف اول نامتان نشان داده می‌شود.",
  "training.lessons.your-profile-photo.step2": "تنظیمات را باز کنید و عکس پروفایل شما را پیدا کنید. عکسی از خودتان انتخاب و ارسال کنید. برای تأیید نزد مالک می‌رود — در مدت انتظار در هیچ‌جا ظاهر نمی‌شود.",
  "training.lessons.your-profile-photo.step3": "وقتی مالک آن را تأیید کند، زنگ شما به صدا درمی‌آید و عکس شما شروع به نمایش می‌کند. اگر تأیید نشد، عکس دیگری انتخاب کنید و آن را ارسال کنید.",
  "training.lessons.your-profile-photo.step4": "تغییر عکس شما نیز به همین صورت است: عکس جدید در انتظار تأیید می‌ماند و عکس فعلی شما تا تأیید عکس جدید در جای خود باقی می‌ماند. اگر تغییری تأیید نشود، عکس قبلی خود را نگه می‌دارید.",
  "training.lessons.owner-profile-photos.title": "عکس‌های پروفایل و نام شما",
  "training.lessons.owner-profile-photos.step1": "عکس هر شخص در بالای برنامه، در صفحه کارکنان شما و در کنار پیام‌هایشان، در کنار نامشان نمایش داده می‌شود. عکس یک عضو تیم تا زمانی که شما آن را تأیید نکنید، در هیچ‌جا ظاهر نمی‌شود — تأیید فقط با شماست و هیچ‌کس نمی‌تواند عکس خودش را تأیید کند.",
  "training.lessons.owner-profile-photos.step2": "وقتی کسی عکسی ارسال می‌کند، زنگ شما به صدا درمی‌آید. صفحه کارکنان را باز کنید تا آن را ببینید، سپس تأیید یا عدم تأیید را انتخاب کنید. اگر آن را تأیید نکنید، به آن شخص گفته می‌شود عکس دیگری انتخاب کند.",
  "training.lessons.owner-profile-photos.step3": "اگر شخصی عکس خود را تغییر دهد، عکس جدید به همان صورت در انتظار تأیید شما می‌ماند. عکس فعلی او در مدت انتظار در جای خود باقی می‌ماند — و اگر تغییر را تأیید نکنید، باقی می‌ماند.",
  "training.lessons.owner-profile-photos.step4": "عکس خودتان نیازی به تأیید ندارد: آن را در تنظیمات، در بخش عکس پروفایل شما تنظیم کنید. همان کارت نام شما را نیز در بر دارد — نامی که در آنجا تنظیم می‌کنید در همه‌جایی که تیمتان می‌بیند، در برنامه و در پیام‌ها، جایگزین واژه مالک می‌شود.",
  "payroll.dd.corrected": "فرم اصلاح‌شده",
