  "training.lessons.owner-dd-setup.step5": "آنچه می‌رسد یک فرم مهروموم‌شده و امضاشده است: از ردیف شخص در حقوق و دستمزد می‌توانید آن را باز کنید تا شماره‌های کامل را بخوانید، چاپش کنید یا یک نسخه ذخیره کنید — هرگز نمی‌توانید ویرایشش کنید. اگر شماره‌ای اشتباه به نظر می‌رسد، فرم را برگردانید: شخص خودش آن را اصلاح می‌کند و دوباره امضا می‌کند، فرم اصلاح‌شده‌اش جای فرم قبلی را می‌گیرد و فرم قبلی با تاریخ جایگزینی‌اش در پرونده می‌ماند.",
  "payroll.profile.ownerNote": "این‌ها جزئیات خودتان در پرونده است، از حساب شما. فقط شما می‌توانید آن‌ها را اینجا ببینید — و چون از آنِ شماست، می‌توانید هر وقت تغییر کردند همین‌جا به‌روزشان کنید.",
