  "staff.memberDialog.clockAccessHint": "فقط مدیران — با این تیک، این مدیر می‌تواند پنجره‌های فراخوان باز کند (به کسی اجازه دهد وقتی شیفت ندارد کار کند) و رکوردهای زمانی را از صفحه کارکنان اصلاح کند. این تیک برای کارکنان هیچ کاری نمی‌کند.",
