  "training.lessons.mgr-clock-callin.title": "فراخوان‌ها و اصلاحات ساعت",
  "training.lessons.mgr-clock-callin.step1": "مالک می‌تواند به یک مدیر یک تیک بدهد — فراخوان‌ها و اصلاحات ساعت. با آن، می‌توانید برای یک کارمند پنجره فراخوان باز کنید و رکوردهای زمانی را از صفحه کارکنان اصلاح کنید.",
  "training.lessons.mgr-clock-callin.step2": "پنجره فراخوان به یک نفر اجازه می‌دهد وقتی هیچ شیفتی او را پوشش نمی‌دهد، وارد شود و ورودش را ثبت کند. آن را از صفحه کارکنان، روی کارت فراخوان‌ها و خروج‌های ثبت‌نشده باز کنید.",
  "training.lessons.mgr-clock-callin.step3": "پنجره تا زمانی که آن شخص خروجش را ثبت کند باز می‌ماند — سپس مهلت معمول ۱۰ دقیقه‌ای پیش از خروج از حساب می‌آید — یا تا زمانی که شما یا مالک آن را زودتر ببندید. هیچ چیز آن را خودبه‌خود نمی‌بندد.",
  "training.lessons.mgr-clock-callin.step4": "وقتی کسی فراموش کند خروجش را ثبت کند، به‌محض پایان شیفت برنامه‌ریزی‌شده، رکوردش در صفحه کارکنان و در حقوق و دستمزد علامت می‌خورد و به شما و مالک اطلاع داده می‌شود. رکورد تا زمانی که اصلاح شود به شمارش ادامه می‌دهد.",
  "training.lessons.mgr-clock-callin.step5": "رکورد را از صفحه کارکنان اصلاح کنید: ورود، خروج و زمان‌های استراحت را تنظیم کنید. یک مدیر فقط رکوردهای کارکنان را اصلاح می‌کند — رکوردهای یک مدیر را مالک اصلاح می‌کند.",
  "staffLib.perm.staffDocuments": "اسناد کارکنان",
  "staffLib.area.documentsAccess": "اسناد کارکنان",
  "staff.memberDialog.documentsAccessHint": "فقط مدیران — با این تیک، این مدیر می‌تواند پرونده‌های اسناد اعضای کارکنان را باز کند: مدارکی که برای هر شخص نگه داشته می‌شود، مانند فرم‌های W-4، درخواست‌های استخدام و کپی مدارک شناسایی. ابتدا از شما تأیید خواسته می‌شود — این پرونده‌ها شامل شماره‌های تأمین اجتماعی و تاریخ‌های تولد هستند. این تیک برای کارکنان هیچ کاری نمی‌کند.",
  "staff.documentsWarning.body": "این شخص می‌تواند اطلاعات محرمانه درباره اعضای کارکنان شما، از جمله شماره‌های تأمین اجتماعی و تاریخ‌های تولد را ببیند.",
