  "staff.documents.desc": "مدارکی که برای هر شخص نگه می‌دارید — فرم‌های W-4، درخواست‌های استخدام، فرم‌های مالیاتی، کپی مدارک شناسایی. فقط شما، و مدیری که تیک اسناد کارکنان را به او بدهید، می‌توانید این پرونده‌ها را باز کنید.",
