  "apiErrors.planGated.crossStoreMessagesPartBusiness": "پیام‌های بین فروشگاهی بخشی از طرح Business است.",
  "apiErrors.invalidValue.personNotPartAccount": "آن شخص بخشی از این حساب نیست.",
  "training.lessons.owner-xstore-messages.title": "پیام‌ها در فروشگاه‌های شما، برای صاحبان",
  "training.lessons.owner-xstore-messages.step1": "پیام‌های بین فروشگاهی صندوق ورودی دومی است، جدا از پیام‌ها. پیام‌ها برای فروشگاهی است که در آن هستید؛ این در به همهٔ افراد حساب شما، در هر کسب‌وکاری که مالک آن هستید، می‌رسد — حداکثر تا پنج کسب‌وکار.",
  "training.lessons.owner-xstore-messages.step2": "پیام‌های بین فروشگاهی را از منو باز کنید و با هر کس در فهرست گفت‌وگو را شروع کنید. فهرست همهٔ اعضای تیم در همهٔ کسب‌وکارهای شما را که وارد شده‌اند، همراه با فروشگاه‌هایی که در آن‌ها کار می‌کنند، نشان می‌دهد.",
  "training.lessons.owner-xstore-messages.step3": "عکس‌ها هم همراه هستند: عکس پروفایل تأییدشدهٔ هر شخص نشان داده می‌شود، یا اگر نداشته باشد حروف اول نامش. هر پیام تاریخ و ساعت ارسالش را دارد.",
  "training.lessons.owner-xstore-messages.step4": "زیر پیام‌های خودتان، به‌محض رسیدن پیام تحویل شد را می‌بینید و وقتی طرف مقابل گفت‌وگو را باز کند خوانده شد را می‌بینید. یادداشت‌های صوتی هم اینجا کار می‌کنند، دقیقاً مانند پیام‌ها.",
  "training.lessons.owner-xstore-messages.step5": "گفت‌وگوهای اینجا میان دو نفری که در آن هستند خصوصی می‌ماند. نظارت شما بر پیام‌های داخل فروشگاه به آن سوی فروشگاه‌ها نمی‌رسد.",
  "training.lessons.mgr-xstore-messages.title": "پیام‌ها در فروشگاه‌های شما، برای مدیران",
  "training.lessons.mgr-xstore-messages.step1": "پیام‌های بین فروشگاهی به همهٔ افراد این حساب، در هر کسب‌وکار می‌رسد — نه فقط فروشگاهی که در آن هستید. این بخش در منو قرار دارد، جدا از پیام‌ها.",
  "training.lessons.mgr-xstore-messages.step2": "از فهرست گفت‌وگو را شروع کنید: هر عضو تیم که وارد شده است آنجا هست، با فروشگاه‌هایی که در آن‌ها کار می‌کند در کنار نامش.",
  "training.lessons.mgr-xstore-messages.step3": "متن بفرستید، یا یک یادداشت صوتی ضبط کنید. پیش از ارسال یادداشت صوتی، می‌توانید آن را گوش دهید، دور بیندازید، یا بفرستید — همان‌طور که در پیام‌ها است.",
  "training.lessons.mgr-xstore-messages.step4": "پیام‌های شما هنگام رسیدن تحویل شد و هنگام باز کردن گفت‌وگو توسط طرف مقابل خوانده شد را نشان می‌دهند. عکس کنار هر نام، عکس پروفایل تأییدشدهٔ آن شخص است.",
  "training.lessons.staff-xstore-messages.title": "پیام‌ها در فروشگاه‌های شما",
  "training.lessons.staff-xstore-messages.step1": "پیام‌های بین فروشگاهی جایی است که می‌توانید به هر کس در این حساب، در هر یک از کسب‌وکارهای مالک برسید — سؤالی برای فروشگاهی دیگر دیگر لازم نیست منتظر بماند.",
  "training.lessons.staff-xstore-messages.step2": "آن را از منو باز کنید، شخص را انتخاب کنید و بنویسید. اگر شخصی که نیاز دارید در فهرست نیست، هنوز وارد نشده است — به‌محض ورود ظاهر می‌شود.",
  "training.lessons.staff-xstore-messages.step3": "اینجا هم می‌توانید یادداشت صوتی بفرستید: ضبط کنید، گوش دهید، سپس بفرستید یا دور بیندازید. هر پیام تاریخ و ساعت ارسالش را نشان می‌دهد.",
  "training.lessons.staff-xstore-messages.step4": "وقتی پیامی می‌فرستید، به‌محض رسیدن تحویل شد و وقتی طرف مقابل گفت‌وگو را باز کند خوانده شد را نشان می‌دهد. گفت‌وگو میان شما و طرف مقابل خصوصی می‌ماند.",
