  "storefronts.disconnect": "قطع اتصال",
  "storefronts.disconnectNote": "قطع اتصال، رسیدن فروش‌های جدید را متوقف می‌کند. فروش‌هایی که قبلاً ثبت شده‌اند در سابقه شما باقی می‌مانند.",
  "storefronts.ebayDesc": "فروشگاه eBay خود را یک بار متصل کنید. وقتی کالایی در eBay فروخته می‌شود، تعداد آن در اینجا خودبه‌خود کاهش می‌یابد و فروش در جابه‌جایی‌های شما ثبت می‌شود — درست مانند اینکه اسکن و خارج شده باشد. فروش‌ها فقط در یک جهت جریان دارند: از eBay به برنامه.",
