  "storefronts.matchingIntro": "{count} کالای فروخته‌شده هنوز نتوانسته‌اند با محصولی مطابقت پیدا کنند. هر یک را به محصولش پیوند دهید و فروش‌های نگه‌داشته‌شده آن خودبه‌خود ثبت می‌شوند — در حین انتظار چیزی از دست نمی‌رود.",
  "storefronts.matchingTitle": "فروش‌هایی که نیاز به مطابقت دارند",
