  "storefronts.recentTitle": "فروش‌های اخیر eBay",
  "storefronts.skuLabel": "SKU",
  "storefronts.staffNote": "مالک یا مدیر از این اتصال مراقبت می‌کند. می‌توانید وضعیت آن را در اینجا ببینید.",
  "storefronts.subtitle": "یک فروشگاه را یک بار متصل کنید و فروش‌های آن موجودی شما را خودبه‌خود به‌روز می‌کنند.",
  "storefronts.title": "اتصالات فروشگاه",
  "training.lessons.owner-ebay-connect.step1": "اتصالات فروشگاه را باز کنید (در گروه فروش) و روی اتصال به eBay بزنید. شما در صفحه خود eBay وارد می‌شوید — برنامه هرگز رمز عبور eBay شما را نمی‌بیند.",
  "training.lessons.owner-ebay-connect.step2": "یک فروشگاه eBay به یک کسب‌وکار متصل می‌شود — کسب‌وکاری که کالاهای آن فروشگاه را می‌فروشد. اگر بیش از یک کسب‌وکار دارید، هر فروشگاه را به کسب‌وکار خودش متصل کنید.",
  "training.lessons.owner-ebay-connect.step3": "مکانی را انتخاب کنید که موجودی eBay شما در آن قرار دارد، تا فروش‌ها از قفسه درست کسر شوند.",
  "training.lessons.owner-ebay-connect.step4": "از آن پس، فروش‌ها خودبه‌خود می‌رسند: وقتی کالایی در eBay فروخته می‌شود، تعداد آن در اینجا کاهش می‌یابد و فروش در جابه‌جایی‌ها با شماره سفارش eBay ثبت می‌شود. هیچ چیزی به عقب جریان نمی‌یابد — برنامه هرگز فهرست‌های eBay شما را تغییر نمی‌دهد.",
  "training.lessons.owner-ebay-connect.step5": "یک فروش بر اساس SKU، UPC یا ISBN مطابقت پیدا می‌کند — هر کدام از این سه که فهرست داشته باشد. اگر فروشی نتواند مطابقت پیدا کند، در بخش «فروش‌هایی که نیاز به مطابقت دارند» در صفحه اتصالات فروشگاه منتظر می‌ماند: آن را یک بار به محصولش پیوند دهید و آن فروش — و فروش‌های آینده مانند آن — خودبه‌خود ثبت می‌شوند. «اکنون فروش‌ها را بررسی کن» هر چیز اخیر را دریافت می‌کند و قطع اتصال، اتصال را متوقف می‌کند؛ فروش‌هایی که قبلاً ثبت شده‌اند باقی می‌مانند.",
  "training.lessons.owner-ebay-connect.title": "فروشگاه eBay خود را متصل کنید",
  "training.module.storefronts": "اتصالات فروشگاه",
